"""Actual live objective choice, counters, save/resume and automatic completion."""
import json,os
from pathlib import Path
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parent
report={'url':os.environ.get('LCK_TEST_URL','http://127.0.0.1:4173'),'checks':[],'errors':[]}
def saved(q):return json.loads(q.evaluate("localStorage.getItem('lck-manager-save-v1')"))
def load(q,s):q.evaluate("s=>sessionStorage.setItem('_qa_next_save',JSON.stringify(s))",s);q.reload(wait_until='domcontentloaded')
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage']);q=b.new_page(viewport={'width':1440,'height':1100},ignore_https_errors=True);q.set_default_timeout(30000);q.on('pageerror',lambda e:report['errors'].append(str(e)));q.add_init_script("const s=sessionStorage.getItem('_qa_next_save');if(s){localStorage.setItem('lck-manager-save-v1',s);sessionStorage.removeItem('_qa_next_save');}")
 q.goto(report['url']);q.locator('[data-action=new-game]').click();q.locator('[data-action=start-season]').click();q.locator('[data-action=next-match]').first.click();q.locator('[data-action=prepare]').first.click();q.locator('[data-action=auto-draft]').click();q.locator('[data-action=assignment-pause]').click();q.locator('[data-action=assignment-auto]').click();q.locator('[data-action=commit-draft]').click();q.locator('[data-action=viewer-speed][data-speed="8"]').click();q.locator('.objective-decision').wait_for();s=saved(q);assert s['activeMatch'];m=next(m for m in s['matches'] if m['id']==s['activeMatch']['matchId']);assert len(m['sets'])==0 and m['score']==[0,0]
 q.wait_for_function("document.querySelector('.objective-decision header small')?.textContent.trim().endsWith(document.querySelector('#live-clock').textContent)");text=q.locator('.objective-decision').inner_text();assert '강타 지수' in text and '골드 교환' in text and '확보 예상' in text;q.screenshot(path=str(ROOT/'2026-objective-decision.png'),full_page=True)
 rng=s['activeMatch']['simulation']['rng'];pending=s['activeMatch']['simulation']['pending'];q.reload();q.locator('.objective-decision').wait_for();assert saved(q)['activeMatch']['simulation']['rng']==rng;assert saved(q)['activeMatch']['simulation']['pending']==pending;report['checks'].append('real UI draft starts live match with no precomputed winner; first objective pauses, scouts smite/secure tools, and survives reload without reroll')
 q.locator('[data-action=objective-choice][data-choice=trade]').click();q.locator('.objective-decision').wait_for();s=saved(q);assert any(e.get('decisions',{}).get(s['myTeam'])=='trade' for e in s['activeMatch']['simulation']['events']);q.locator('[data-action=objective-choice][data-choice=contest]').click();q.locator('.objective-decision').wait_for();s=saved(q);assert any(e.get('decisions',{}).get(s['myTeam'])=='contest' for e in s['activeMatch']['simulation']['events']);report['checks'].append('trade and contest choices actually alter objective decisions, events and gold')
 q.set_viewport_size({'width':390,'height':844});q.locator('.objective-decision').scroll_into_view_if_needed();assert q.locator('[data-action=objective-choice][data-choice=auto]').is_visible();assert q.evaluate('document.documentElement.scrollWidth<=innerWidth');q.screenshot(path=str(ROOT/'2026-objective-mobile.png'),full_page=True)
 q.locator('[data-action=objective-choice][data-choice=auto]').click();q.locator('.objective-decision').wait_for();q.locator('[data-action=match-auto]').click();s=saved(q);assert s['activeMatch'] is None;m=next(m for m in s['matches'] if m['id']==s['viewing']['matchId']);z=m['sets'][-1];assert z['simulationReplay']['model']=='event-v5';assert len(z['objectiveTotals'])==10;report['checks'].append('390px choice dialog, one-decision auto and remaining-set auto complete and persist the live match')
 q.wait_for_function("document.querySelector('.live-scoreboard [data-grubs]')?.textContent!=='0' || document.querySelector('.live-scoreboard [data-dragons]')?.textContent!=='0'")
 for side,index in [('blue',0),('red',1)]:
  team=z[side];assert q.locator(f'.live-scoreboard [data-grubs="{team}"]').inner_text()==str(z['objectiveTotals'][index]);assert q.locator(f'.live-scoreboard [data-dragons="{team}"]').inner_text()==str(z['objectiveTotals'][8+index])
 report['checks'].append('both teams dragon and individual-grub scoreboard counts equal the actual saved captures')
 # Completed AI replay also has real counts and variable events, without spawning choice dialogs.
 q.set_viewport_size({'width':1440,'height':1100});q.screenshot(path=str(ROOT/'2026-objective-counts.png'),full_page=True);assert q.locator('.objective-decision').count()==0
 assert not report['errors'],report['errors'];Path(os.environ.get('LCK_TEST_REPORT',str(ROOT/'objectives-macro-browser-results.json'))).write_text(json.dumps(report,ensure_ascii=False,indent=2));print(json.dumps(report,ensure_ascii=False));b.close()
